import {geoInstancedTexEffect} from "../../shaders/standalone/geo.tex.js";
import {GeometryFactory} from "../geometry-factory.js";
import {mat4} from "wgpu-matrix";
// ?
export class GenGeoTexture {
  static _pipelineCache = new WeakMap();
  constructor(device, format, type = "sphere", path, scale = 1, cameraBuffer) {
    this.device = device;
    this.format = format;
    this.cameraBuffer = cameraBuffer;
    const geom = GeometryFactory.create(type, scale);
    this.vertexData = geom.positions;
    this.uvData = geom.uvs;
    this.indexData = geom.indices;
    this.enabled = true;
    this._localMatrix = new Float32Array(16);
    this._finalMatrix = new Float32Array(16);
    this.rotateEffect = true;
    this.rotateEffectSpeed = 10;
    this.rotateAngle = 0;
    this.loadTexture(path).then(() => {
      this._initPipeline();
    })
  }

  async loadTexture(url) {
    return new Promise(async (resolve, reject) => {
      const img = await fetch(url).then(r => r.blob()).then(createImageBitmap);
      const texture = this.device.createTexture({
        size: [img.width, img.height, 1],
        format: "rgba8unorm",
        usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST | GPUTextureUsage.RENDER_ATTACHMENT,
      });

      this.device.queue.copyExternalImageToTexture(
        {source: img},
        {texture},
        [img.width, img.height]
      );

      const sampler = this.device.createSampler({
        magFilter: "linear",
        minFilter: "linear",
        addressModeU: "repeat",
        addressModeV: "repeat"
      });

      this.texture = texture;
      this.sampler = sampler;
      resolve()
    })
  }

_initPipeline() {
  const device = this.device;
  const {vertexData, uvData, indexData} = this;

  // ========== CACHE CHECK ==========
  if (GenGeoTexture._pipelineCache.has(device)) {
    const cached = GenGeoTexture._pipelineCache.get(device);
    this.pipeline = cached.pipeline;
    this.bindGroupLayout = cached.bindGroupLayout;
    this.pipelineLayout = cached.pipelineLayout;
    this.shaderModule = cached.shaderModule;
  } else {
    // ========== BUILD PIPELINE ONCE ==========
    this.bindGroupLayout = device.createBindGroupLayout({
      entries: [
        {binding: 0, visibility: GPUShaderStage.VERTEX, buffer: {}},
        {binding: 1, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: {type: "read-only-storage"}},
        {binding: 2, visibility: GPUShaderStage.FRAGMENT, sampler: {}},
        {binding: 3, visibility: GPUShaderStage.FRAGMENT, texture: {}},
      ],
    });

    this.shaderModule = device.createShaderModule({code: geoInstancedTexEffect()});
    this.pipelineLayout = device.createPipelineLayout({bindGroupLayouts: [this.bindGroupLayout]});

    this.pipeline = device.createRenderPipeline({
      label: 'gen-geo-tex pipeline',
      layout: this.pipelineLayout,
      vertex: {
        module: this.shaderModule,
        entryPoint: 'vsMain',
        buffers: [
          {arrayStride: 12, attributes: [{shaderLocation: 0, offset: 0, format: 'float32x3'}]},
          {arrayStride: 8, attributes: [{shaderLocation: 1, offset: 0, format: 'float32x2'}]}
        ]
      },
      fragment: {
        module: this.shaderModule,
        entryPoint: 'fsMain',
        targets: [{
          format: this.format,
          blend: {
            color: {
              srcFactor: 'src-alpha',
              dstFactor: 'one-minus-src-alpha',
              operation: 'add',
            },
            alpha: {
              srcFactor: 'one',
              dstFactor: 'one-minus-src-alpha',
              operation: 'add',
            },
          },
        }, {format: 'rgba16float'},
        {format: 'rgba16float'}]
      },
      primitive: {topology: 'triangle-list'},
      depthStencil: {depthWriteEnabled: false, depthCompare: 'less-equal', format: 'depth24plus'}
    });

    
    GenGeoTexture._pipelineCache.set(device, {
      pipeline: this.pipeline,
      bindGroupLayout: this.bindGroupLayout,
      pipelineLayout: this.pipelineLayout,
      shaderModule: this.shaderModule
    });
  }

  
  this.vertexBuffer = device.createBuffer({
    size: vertexData.byteLength,
    usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST
  });
  device.queue.writeBuffer(this.vertexBuffer, 0, vertexData);

  this.uvBuffer = device.createBuffer({
    size: uvData.byteLength,
    usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST
  });
  device.queue.writeBuffer(this.uvBuffer, 0, uvData);

  this.indexBuffer = device.createBuffer({
    size: Math.ceil(indexData.byteLength / 4) * 4,
    usage: GPUBufferUsage.INDEX | GPUBufferUsage.COPY_DST
  });
  device.queue.writeBuffer(this.indexBuffer, 0, indexData);
  this.indexCount = indexData.length;

  this.instanceTargets = [];
  this.lerpSpeed = 0.05;
  this.maxInstances = 5;
  this.instanceCount = 2;
  this.floatsPerInstance = 16 + 4;

  for(let x = 0; x < this.maxInstances; x++) {
    this.instanceTargets.push({
      index: x,
      position: [0, 0, 0],
      currentPosition: [0, 0, 0],
      scale: [1, 1, 1],
      currentScale: [1, 1, 1],
      color: [0.6, 0.8, 1.0, 0.4],
    });
  }

  this.instanceData = new Float32Array(this.instanceCount * this.floatsPerInstance);
  this.modelBuffer = device.createBuffer({
    size: this.instanceData.byteLength,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
  });

  this.bindGroup = device.createBindGroup({
    layout: this.bindGroupLayout,
    entries: [
      {binding: 0, resource: {buffer: this.cameraBuffer}},
      {binding: 1, resource: {buffer: this.modelBuffer}},
      {binding: 2, resource: this.sampler},
      {binding: 3, resource: this.texture.createView()},
    ]
  });
}

  updateInstanceData = (baseModelMatrix) => {
    if(this.rotateEffect) {
      this.rotateAngle = (this.rotateAngle ?? 0) + this.rotateEffectSpeed; // accumulate rotation
      if(this.rotateAngle >= 360) {
        this.rotateAngle = 0;
      }
    }
    const count = Math.min(this.instanceCount, this.maxInstances);
    for(let i = 0;i < count;i++) {
      const t = this.instanceTargets[i];
      for(let j = 0;j < 3;j++) {
        t.currentPosition[j] += (t.position[j] - t.currentPosition[j]) * this.lerpSpeed;
        t.currentScale[j] += (t.scale[j] - t.currentScale[j]) * this.lerpSpeed;
      }

      mat4.identity(this._localMatrix);
      if(this.rotateEffect) {
        mat4.rotateY(this._localMatrix, this.rotateAngle, this._localMatrix);
      }
      mat4.translate(this._localMatrix, t.currentPosition, this._localMatrix);
      mat4.scale(this._localMatrix, t.currentScale, this._localMatrix);
      mat4.identity(this._finalMatrix);
      mat4.multiply(baseModelMatrix, this._localMatrix, this._finalMatrix);

      const offset = i * this.floatsPerInstance;
      this.instanceData.set(this._finalMatrix, offset);
      this.instanceData[offset + 16] = t.color[0];
      this.instanceData[offset + 17] = t.color[1];
      this.instanceData[offset + 18] = t.color[2];
      this.instanceData[offset + 19] = t.color[3];
    }
    // IMPORTANT: upload ONLY the active range of floats to GPU to avoid leftover instances
    const activeFloatCount = count * this.floatsPerInstance;
    this.device.queue.writeBuffer(this.modelBuffer, 0, this.instanceData.subarray(0, activeFloatCount));
  };

  draw(pass, cameraMatrix) {
    this.device.queue.writeBuffer(this.cameraBuffer, 0, cameraMatrix);
    // pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bindGroup);
    pass.setVertexBuffer(0, this.vertexBuffer);
    pass.setVertexBuffer(1, this.uvBuffer);
    pass.setIndexBuffer(this.indexBuffer, 'uint16');
    pass.drawIndexed(this.indexCount, this.instanceCount);
  }

  render(pass, mesh, viewProjMatrix, dt = 0.1) {
    if(!this.activeCount) return;
    this.device.queue.writeBuffer(this.cameraBuffer, 0, viewProjMatrix);
    // pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bindGroup);
    pass.setVertexBuffer(0, this.vertexBuffer);
    pass.setVertexBuffer(1, this.uvBuffer);
    pass.setIndexBuffer(this.indexBuffer, "uint16");
    pass.drawIndexed(this.indexCount, this.activeCount);
  }
}