import {pointEffectShader} from "../../shaders/topology-point/pointEffect";

export class PointEffect {
  static _pipelineCache = new WeakMap();
  constructor(device, format, cameraBuffer) {
    this.device = device;
    this.format = format;
    this.cameraBuffer = cameraBuffer;
    this.pointSize = 8.0;
    this.enabled = true;
    this._pointSettingsScratch = new Float32Array(4);
    this._initPipeline();
  }

  _initPipeline() {
    const device = this.device;
    if(TopologyEffect._pipelineCache.has(device)) {
      const cached = TopologyEffect._pipelineCache.get(device);
      this.bindGroupLayout = cached.bindGroupLayout;
      this.shaderModule = cached.shaderModule;
      this.pipelineLayout = cached.pipelineLayout;
      this.pipeline = cached.pipeline;
    } else {
      this.bindGroupLayout = device.createBindGroupLayout({
        entries: [
          {binding: 0, visibility: GPUShaderStage.VERTEX, buffer: {}},
          {binding: 1, visibility: GPUShaderStage.VERTEX, buffer: {}},
          {binding: 2, visibility: GPUShaderStage.VERTEX, buffer: {}},
        ]
      });
      this.shaderModule = device.createShaderModule({code: pointEffectShader});
      this.pipelineLayout = device.createPipelineLayout({
        bindGroupLayouts: [this.bindGroupLayout]
      });

      this.pipeline = device.createRenderPipeline({
        label: 'Topology Pipeline',
        layout: this.pipelineLayout,
        vertex: {
          module: this.shaderModule,
          entryPoint: "vsMain",
          buffers: [
            {
              arrayStride: 3 * 4,
              stepMode: 'instance',
              attributes: [{shaderLocation: 0, offset: 0, format: "float32x3"}]
            },
            {
              arrayStride: 3 * 4,
              stepMode: 'instance',
              attributes: [{shaderLocation: 1, offset: 0, format: "float32x3"}]
            }
          ]
        },
        fragment: {
          module: this.shaderModule,
          entryPoint: "fsMain",
          targets: [{
            format: this.format,
            blend: {
              color: {srcFactor: "src-alpha", dstFactor: "one-minus-src-alpha", operation: "add"},
              alpha: {srcFactor: "one", dstFactor: "one-minus-src-alpha", operation: "add"}
            }
          }, {format: 'rgba16float'}, {format: 'rgba16float'}]
        },
        primitive: {topology: "triangle-strip"},
        depthStencil: {
          depthWriteEnabled: false,
          depthCompare: "less-equal",
          format: "depth24plus"
        }
      });

      // ========== CACHE THEM ==========
      TopologyEffect._pipelineCache.set(device, {
        bindGroupLayout: this.bindGroupLayout,
        shaderModule: this.shaderModule,
        pipelineLayout: this.pipelineLayout,
        pipeline: this.pipeline
      });
    }

    // ========== PER-INSTANCE BUFFERS (NOT CACHED) ==========
    this.modelBuffer = device.createBuffer({
      size: 64,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
    });

    this.pointSettingsBuffer = device.createBuffer({
      size: 32,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
    });

    this._pointSettingsScratch[0] = this.pointSize;
    device.queue.writeBuffer(this.pointSettingsBuffer, 0, this._pointSettingsScratch);

    this.bindGroup = device.createBindGroup({
      layout: this.bindGroupLayout,
      entries: [
        {binding: 0, resource: {buffer: this.cameraBuffer}},
        {binding: 1, resource: {buffer: this.modelBuffer}},
        {binding: 2, resource: {buffer: this.pointSettingsBuffer}},
      ]
    });

  }

  updateInstanceData(baseModelMatrix) {
    // You can apply additional transforms here if needed
    // For now, just use the parent's model matrix directly
    this.device.queue.writeBuffer(this.modelBuffer, 0, baseModelMatrix);
  }

  draw(pass, cameraMatrix, vertexBuffer, colorBuffer, vertexCount) {
    if(!this.enabled) return;
    if(!vertexCount || typeof vertexCount !== 'number' || vertexCount <= 0) {
      console.warn('PointEffect: invalid vertexCount', vertexCount);
      return;
    }
    this.device.queue.writeBuffer(this.cameraBuffer, 0, cameraMatrix);
    // pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bindGroup);
    pass.setVertexBuffer(0, vertexBuffer);
    pass.setVertexBuffer(1, colorBuffer);
    pass.draw(4, vertexCount, 0, 0);
  }

  render(pass, mesh, viewProjMatrix) {
    if(!mesh.vertexBuffer) {
      console.warn('PointEffect: mesh has no vertexBuffer');
      return;
    }
    let vertexCount = mesh.vertexCount;
    if(!vertexCount && mesh.vertexBuffer.size) {
      vertexCount = mesh.vertexBuffer.size / (3 * 4);
    }
    if(!vertexCount && mesh.geometry?.positions) {
      vertexCount = mesh.geometry.positions.length / 3;
    }
    if(!vertexCount || vertexCount <= 0) {
      console.warn('PointEffect: could not determine vertexCount', mesh);
      return;
    }
    const colorBuffer = mesh.vertexNormalsBuffer;
    if(!colorBuffer) {
      console.warn('PointEffect: mesh has no vertexNormalsBuffer');
      return;
    }
    this.draw(pass, viewProjMatrix, mesh.vertexBuffer, colorBuffer, vertexCount);
  }

  setPointSize(size) {
    this.pointSize = size;
    this._pointSettingsScratch[0] = size;
    this._pointSettingsScratch[1] = 0;
    this._pointSettingsScratch[2] = 0;
    this._pointSettingsScratch[3] = 0;
    this.device.queue.writeBuffer(this.pointSettingsBuffer, 0, this._pointSettingsScratch);
  }

  setEnabled(enabled) {
    this.enabled = enabled;
  }
}