import {mat4} from "wgpu-matrix";
import {
  fullscreenVertShader, dropFragShader, sphereFragShader,
  causticsVertShader, causticsFragShader, surfaceVertShaderSphere, updateFragShaderSphere,
  normalFragShaderSphere, surfaceFragShaderSphere
} from "../../shaders/water-simulation/water-simulation.wgsl";
import {GeometryFactory} from "../geometry-factory";

const SIM_RES = 512;
export class WaterSimSphereEffect {
  static _pipelineCache = new WeakMap();
  constructor(device, format, options = {}) {
    this.device = device;
    this.format = format;
    this.enabled = true;

    // Store options as instance properties (needed by initPipeline helpers)
    this.opacity = options.opacity ?? 0.2;
    this.geometryType = options.geometryType ?? (options.isSphere ? 'sphere' : 'sphere');
    this.geometryOptions = options.geometryOptions ?? {};
    this.normalizeToUnitSphere = options.normalizeToUnitSphere ?? true;
    this.isSphere = options.isSphere ?? true;
    this.gpuBlend = options.gpuBlend ?? {
      color: {srcFactor: 'src-alpha', dstFactor: 'one-minus-src-alpha', operation: 'add'},
      alpha: {srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add'}
    };
    this.width = options.width ?? SIM_RES;
    this.height = options.height ?? SIM_RES;
    this.size = options.size ?? 10;
    this.detail = options.detail ?? 64;
    this.poolHeight = options.poolHeight ?? 0.10;
    this.ior = options.ior ?? 1.333;
    this.fresnelMin = options.fresnelMin ?? 0.25;
    this.causticIntensity = options.causticIntensity ?? 0.3;
    this.lightDirection = options.lightDirection ?? [2.0, 2.0, -1.0];

    this._dropQueue = [];
    this._sphereStamp = null;
    this._simFormat = device.features.has('float32-filterable') ? 'rgba32float' : 'rgba16float';
    this._localMatrix = mat4.create();
    this._finalMatrix = mat4.create();
    this.data = new Float32Array(20);
    this.data2 = new Float32Array(12);
    this._idleFrames = 0;
    this._idleThreshold = 90;
    this.vertexCount = 0; // Will be set in _createSurfaceMesh

    // Call initPipeline — it handles cache check and all pipeline/buffer creation
    this.initPipeline();
  }

  destroy() {
    if(this.textureA) this.textureA.destroy();
    if(this.textureB) this.textureB.destroy();
    if(this.causticsTexture) this.causticsTexture.destroy();
    if(this.floorTexture) this.floorTexture.destroy();

    if(this.vertexBuffer) this.vertexBuffer.destroy();
    if(this.indexBuffer) this.indexBuffer.destroy();
    if(this.dummyPosBuffer) this.dummyPosBuffer.destroy();
    if(this.colorBuffer) this.colorBuffer.destroy();
    if(this.scaleBuffer) this.scaleBuffer.destroy();
    if(this.modelBuffer) this.modelBuffer.destroy();
    if(this.commonUniformBuffer) this.commonUniformBuffer.destroy();
    if(this.lightUniformBuffer) this.lightUniformBuffer.destroy();
    if(this.waterUniformBuffer) this.waterUniformBuffer.destroy();

    if(this.dropPipeline?.uniformBuffer) this.dropPipeline.uniformBuffer.destroy();
    if(this.updatePipeline?.uniformBuffer) this.updatePipeline.uniformBuffer.destroy();
    if(this.normalPipeline?.uniformBuffer) this.normalPipeline.uniformBuffer.destroy();
    if(this.spherePipeline?.uniformBuffer) this.spherePipeline.uniformBuffer.destroy();
  }

  initPipeline() {
    const device = this.device;

    // ========== CACHE CHECK ==========
    if(WaterSimSphereEffect._pipelineCache.has(device)) {
      const cached = WaterSimSphereEffect._pipelineCache.get(device);
      // Surface pipelines (shared, device-wide)
      this.surfaceBindGroupLayout = cached.surfaceBindGroupLayout;
      this.surfacePipelineLayout = cached.surfacePipelineLayout;
      this.surfacePipelineAbove = cached.surfacePipelineAbove;
      this.surfacePipelineUnder = cached.surfacePipelineUnder;
      // Sim pipelines (just the pipeline objects, not uniform buffers or bind groups)
      this._cachedSimPipelines = cached.simPipelines;
      // Caustics pipeline
      this.causticsPipeline = cached.causticsPipeline;
    } else {
      // ========== BUILD PIPELINES ONCE (DEVICE-WIDE) ==========
      this.surfaceBindGroupLayout = device.createBindGroupLayout({
        label: 'WaterSim Surface BGL',
        entries: [
          {binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: {type: 'uniform'}},
          {binding: 1, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: {type: 'uniform'}},
          {binding: 2, visibility: GPUShaderStage.FRAGMENT, buffer: {type: 'uniform'}},
          {binding: 3, visibility: GPUShaderStage.FRAGMENT, buffer: {type: 'uniform'}},
          {binding: 4, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, sampler: {}},
          {binding: 5, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, texture: {}},
          {binding: 6, visibility: GPUShaderStage.FRAGMENT, sampler: {}},
          {binding: 7, visibility: GPUShaderStage.FRAGMENT, texture: {}},
          {binding: 8, visibility: GPUShaderStage.FRAGMENT, texture: {}}
        ]
      });

      this.surfacePipelineLayout = device.createPipelineLayout({bindGroupLayouts: [this.surfaceBindGroupLayout]});
      const surfaceVSModule = device.createShaderModule({label: 'WaterSim S VS', code: surfaceVertShaderSphere});
      const surfaceFSModule = device.createShaderModule({label: 'WaterSim S FS', code: surfaceFragShaderSphere});

      const baseDesc = {
        layout: this.surfacePipelineLayout,
        vertex: {
          module: surfaceVSModule,
          entryPoint: 'vs_main',
          buffers: [{arrayStride: 12, attributes: [{shaderLocation: 0, offset: 0, format: 'float32x3'}]}]
        },
        fragment: {
          module: surfaceFSModule, entryPoint: 'fs_main', targets: [
            {format: this.format, blend: this.gpuBlend},
            {format: this.format}, {format: this.format}
          ]
        },
        primitive: {topology: 'triangle-list'},
        depthStencil: {depthWriteEnabled: true, depthCompare: 'less', format: 'depth24plus'}
      };

      this.surfacePipelineAbove = device.createRenderPipeline({
        ...baseDesc, label: 'WaterSim S Above',
        primitive: {topology: 'triangle-list', cullMode: 'back'}
      });
      this.surfacePipelineUnder = device.createRenderPipeline({
        ...baseDesc, label: 'WaterSim S Under',
        depthStencil: {depthWriteEnabled: false, depthCompare: 'less-equal', format: 'depth24plus'},
        primitive: {topology: 'triangle-list', cullMode: 'front'}
      });

      // Sim pipelines (store just the pipeline objects)
      this._cachedSimPipelines = {
        drop: this._buildSimPipelineShaderAndPipeline('Drop', dropFragShader),
        update: this._buildSimPipelineShaderAndPipeline('Update', updateFragShaderSphere),
        normal: this._buildSimPipelineShaderAndPipeline('Normal', normalFragShaderSphere),
        sphere: this._buildSimPipelineShaderAndPipeline('Sphere', sphereFragShader)
      };

      // Caustics pipeline
      const causticsVSModule = device.createShaderModule({label: 'WaterSim Caustics VS', code: causticsVertShader});
      const causticsFSModule = device.createShaderModule({label: 'WaterSim Caustics FS', code: causticsFragShader});
      this.causticsPipeline = device.createRenderPipeline({
        label: 'WaterSim Caustics',
        layout: 'auto',
        vertex: {
          module: causticsVSModule,
          entryPoint: 'vs_main',
          buffers: [{arrayStride: 12, attributes: [{shaderLocation: 0, offset: 0, format: 'float32x3'}]}]
        },
        fragment: {
          module: causticsFSModule,
          entryPoint: 'fs_main',
          targets: [{
            format: 'rgba8unorm',
            blend: {
              color: {srcFactor: 'src-alpha', dstFactor: 'one-minus-src-alpha', operation: 'add'},
              alpha: {srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add'}
            }
          }]
        },
        primitive: {topology: 'triangle-list'}
      });

      // ========== CACHE THEM ==========
      WaterSimSphereEffect._pipelineCache.set(device, {
        surfaceBindGroupLayout: this.surfaceBindGroupLayout,
        surfacePipelineLayout: this.surfacePipelineLayout,
        surfacePipelineAbove: this.surfacePipelineAbove,
        surfacePipelineUnder: this.surfacePipelineUnder,
        simPipelines: this._cachedSimPipelines,
        causticsPipeline: this.causticsPipeline
      });
    }

    // ========== PER-INSTANCE RESOURCES (NOT CACHED) ==========
    this._createTextures();
    this._simPassDescs = [
      {colorAttachments: [{view: this._physViews[0], loadOp: 'clear', storeOp: 'store', clearValue: {r: 0, g: 0, b: 0, a: 0}}]},
      {colorAttachments: [{view: this._physViews[1], loadOp: 'clear', storeOp: 'store', clearValue: {r: 0, g: 0, b: 0, a: 0}}]}
    ];
    this._causticsView = this.causticsTexture.createView();
    this._causticsPassDesc = {
      colorAttachments: [{view: this._causticsView, loadOp: 'clear', storeOp: 'store', clearValue: {r: 0, g: 0, b: 0, a: 0}}]
    };

    this._dropUniform = new Float32Array(4);
    this._sphereUniform = new Float32Array(8);
    this._deltaUniform = new Float32Array([1 / this.width, 1 / this.height]);
    this._defaultEye = [0, 5, 5];

    this._createSampler();
    this._createUniformBuffers(this.constructor.options ?? {});
    this._createSimPipelineBG(); // Create per-instance bind groups for cached sim pipelines
    this._createSurfaceMesh();
    this._createSurfaceBindGroups();
    this._createCausticsBindGroups();
  }

  // Helper: create just the shader module and pipeline for sim (no uniform buffer or bind groups)
  _buildSimPipelineShaderAndPipeline(label, fragCode) {
    const module = this.device.createShaderModule({
      label: label + ' Sim Module',
      code: fullscreenVertShader + fragCode
    });
    const pipeline = this.device.createRenderPipeline({
      label: label + ' Sim Pipeline',
      layout: 'auto',
      vertex: {module, entryPoint: 'vs_main'},
      fragment: {module, entryPoint: 'fs_main', targets: [{format: this._simFormat}]},
      primitive: {topology: 'triangle-list'}
    });
    return pipeline;
  }

  // Helper: create per-instance uniform buffers and bind groups for cached sim pipelines
  _createSimPipelineBG() {
    const createSimPipelineObj = (pipeline, uniformSize) => {
      const uniformBuffer = this.device.createBuffer({
        size: uniformSize,
        usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
      });
      const makeBG = (readView) => this.device.createBindGroup({
        layout: pipeline.getBindGroupLayout(0),
        entries: [
          {binding: 0, resource: readView},
          {binding: 1, resource: this.sampler},
          {binding: 2, resource: {buffer: uniformBuffer}}
        ]
      });
      return {
        pipeline,
        uniformBuffer,
        bindGroups: [makeBG(this._physViews[0]), makeBG(this._physViews[1])]
      };
    };

    this.dropPipeline = createSimPipelineObj(this._cachedSimPipelines.drop, 32);
    this.updatePipeline = createSimPipelineObj(this._cachedSimPipelines.update, 16);
    this.normalPipeline = createSimPipelineObj(this._cachedSimPipelines.normal, 16);
    this.spherePipeline = createSimPipelineObj(this._cachedSimPipelines.sphere, 32);
  }

  // Helper: create per-instance surface bind groups (uses cached pipelines/layouts)
  _createSurfaceBindGroups() {
    this.modelBuffer = this.device.createBuffer({
      label: "WaterSim Model Buff",
      size: 96,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
    });

    const makeBG = (waterView) => this.device.createBindGroup({
      layout: this.surfaceBindGroupLayout,
      entries: [
        {binding: 0, resource: {buffer: this.commonUniformBuffer}},
        {binding: 1, resource: {buffer: this.modelBuffer}},
        {binding: 2, resource: {buffer: this.lightUniformBuffer}},
        {binding: 3, resource: {buffer: this.waterUniformBuffer}},
        {binding: 4, resource: this.sampler},
        {binding: 5, resource: waterView},
        {binding: 6, resource: this.floorSampler},
        {binding: 7, resource: this.floorTexture.createView()},
        {binding: 8, resource: this.causticsTexture.createView()}
      ]
    });
    this._surfaceBindGroups = [makeBG(this._physViews[0]), makeBG(this._physViews[1])];
  }

  // Helper: create per-instance caustics bind groups (uses cached pipeline)
  _createCausticsBindGroups() {
    const makeBG = (waterView) => this.device.createBindGroup({
      layout: this.causticsPipeline.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.lightUniformBuffer}},
        {binding: 1, resource: {buffer: this.waterUniformBuffer}},
        {binding: 2, resource: this.sampler},
        {binding: 3, resource: waterView}
      ]
    });
    this._causticsBindGroups = [makeBG(this._physViews[0]), makeBG(this._physViews[1])];
  }

  useExternalGeometry(positionBuffer, indexBuffer, indexCount, indexFormat = 'uint32') {
    this.positionBuffer = positionBuffer;
    this.indexBuffer = indexBuffer;
    this.indexCount = indexCount;
    this._indexFormat = indexFormat;
  }

  updateInstanceData(baseModelMatrix) {
    mat4.identity(this._localMatrix);
    mat4.multiply(baseModelMatrix, this._localMatrix, this._finalMatrix);
    this.device.queue.writeBuffer(this.modelBuffer, 0, this._finalMatrix);
    const posX = this._finalMatrix[12];
    const posY = this._finalMatrix[13];
    const posZ = this._finalMatrix[14];
    this.data2.set([this.ior, this.fresnelMin, this.causticIntensity, this.poolHeight, this.size, posX ?? 0, posY ?? 0, posZ ?? 0, this.opacity]);
    this.device.queue.writeBuffer(this.waterUniformBuffer, 0, this.data2);
  }

  _createTextures() {
    const texDesc = {
      size: [this.width, this.height],
      format: this._simFormat,
      usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.RENDER_ATTACHMENT
    };
    this.textureA = this.device.createTexture({...texDesc, label: 'WaterSim A'});
    this.textureB = this.device.createTexture({...texDesc, label: 'WaterSim B'});
    // Fixed for the lifetime of the effect - views are cheap to cache once
    // and index by parity instead of recreating them on every sim pass.
    this._physViews = [this.textureA.createView(), this.textureB.createView()];
    this._parity = 0; // 0 = textureA is "current" (readable) state

    this.causticsTexture = this.device.createTexture({
      label: 'WaterSim Caustics',
      size: [512, 512],
      format: 'rgba8unorm',
      usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.RENDER_ATTACHMENT
    });

    // Default flat floor texture (1x1 gray) so the surface pipeline always
    // has a valid binding even if the caller doesn't supply one.
    this.floorTexture = this.device.createTexture({
      label: 'WaterSim Default Floor',
      size: [1, 1],
      format: 'rgba8unorm',
      usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST
    });
    this.device.queue.writeTexture(
      {texture: this.floorTexture},
      new Uint8Array([90, 95, 100, 255]),
      {bytesPerRow: 4},
      {width: 1, height: 1}
    );
  }

  _createSampler() {
    this.sampler = this.device.createSampler({
      magFilter: 'linear',
      minFilter: 'linear',
      addressModeU: 'clamp-to-edge',
      addressModeV: 'clamp-to-edge'
    });
  }

  _createUniformBuffers(options) {
    this.commonUniformBuffer = this.device.createBuffer({
      label: 'WaterSim Common Uniforms',
      size: 80,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
    });
    this.lightUniformBuffer = this.device.createBuffer({
      label: 'WaterSim Light Uniforms',
      size: 16,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
    });
    this.waterUniformBuffer = this.device.createBuffer({
      label: 'WaterSim Water Uniforms',
      size: 48, // was 32 — now 9 floats + padding
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
    });
    this._writeLightUniforms();
    this._writeWaterUniforms();
    this.floorSampler = options.floorSampler ?? this.device.createSampler({
      magFilter: 'linear', minFilter: 'linear',
      addressModeU: 'repeat', addressModeV: 'repeat'
    });
    if(options.floorTexture) this.floorTexture = options.floorTexture;
  }

  _writeLightUniforms() {
    const [x, y, z] = this.lightDirection;
    const len = Math.hypot(x, y, z) || 1;
    this.device.queue.writeBuffer(this.lightUniformBuffer, 0,
      new Float32Array([x / len, y / len, z / len, 0]));
  }

  _writeWaterUniforms() {
    this.data2.set([this.ior, this.fresnelMin, this.causticIntensity, this.poolHeight, this.size, 0, 0, 0]);
    this.device.queue.writeBuffer(this.waterUniformBuffer, 0, this.data2);
  }

  _createSimPipelines() {
    this.dropPipeline = this._buildSimPipeline('Drop', dropFragShader, 32);
    this.updatePipeline = this._buildSimPipeline('Update', updateFragShaderSphere, 16);
    this.normalPipeline = this._buildSimPipeline('Normal', normalFragShaderSphere, 16);
    this.spherePipeline = this._buildSimPipeline('Sphere', sphereFragShader, 32);
  }

  _buildSimPipeline(label, fragCode, uniformSize) {
    const module = this.device.createShaderModule({
      label: label + ' Sim Module',
      code: fullscreenVertShader + fragCode
    });
    const pipeline = this.device.createRenderPipeline({
      label: label + ' Sim Pipeline',
      layout: 'auto',
      vertex: {module, entryPoint: 'vs_main'},
      fragment: {module, entryPoint: 'fs_main', targets: [{format: this._simFormat}]},
      primitive: {topology: 'triangle-list'}
    });
    const uniformBuffer = this.device.createBuffer({
      size: uniformSize,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
    });
    const makeBG = (readView) => this.device.createBindGroup({
      layout: pipeline.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: readView},
        {binding: 1, resource: this.sampler},
        {binding: 2, resource: {buffer: uniformBuffer}}
      ]
    });
    return {
      pipeline,
      uniformBuffer,
      bindGroups: [makeBG(this._physViews[0]), makeBG(this._physViews[1])]
    };
  }

  _createSurfaceMesh() {
    const detail = this.detail;
    let positions, indices;
    if(this.geometryType === 'plane') {
      positions = [];
      indices = [];
      for(let z = 0;z <= detail;z++) {
        const t = z / detail;
        for(let x = 0;x <= detail;x++) {
          const s = x / detail;
          positions.push(2.0 * s - 1.0, 0.0, 2.0 * t - 1.0);
        }
      }
      for(let z = 0;z < detail;z++) {
        for(let x = 0;x < detail;x++) {
          const i = x + z * (detail + 1);
          indices.push(i, i + 1, i + detail + 1, i + detail + 1, i + 1, i + detail + 2);
        }
      }
      positions = new Float32Array(positions);
      indices = new Uint32Array(indices);
    } else {
      const geo = GeometryFactory.create(this.geometryType, 1, detail, this.geometryOptions);
      positions = geo.positions.slice();
      indices = geo.indices;

      if(this.normalizeToUnitSphere) {
        for(let i = 0;i < positions.length;i += 3) {
          const x = positions[i], y = positions[i + 1], z = positions[i + 2];
          const len = Math.hypot(x, y, z);
          if(len < 1e-6) continue; // origin-anchored vertex, see warning below — leave as-is rather than divide by ~0
          positions[i] = x / len;
          positions[i + 1] = y / len;
          positions[i + 2] = z / len;
        }
      }
    }

    this.indexCount = indices.length;

    this.positionBuffer = this.device.createBuffer({
      label: 'WaterSim Surface V', size: positions.length * 4,
      usage: GPUBufferUsage.VERTEX, mappedAtCreation: true
    });
    new Float32Array(this.positionBuffer.getMappedRange()).set(positions);
    this.positionBuffer.unmap();

    // normalize index type regardless of what GeometryFactory returns (Uint16 or Uint32) —
    // this class's buffer/format has always assumed uint32, keep it consistent
    const idx32 = indices instanceof Uint32Array ? indices : Uint32Array.from(indices);
    this._indexFormat = 'uint32';
    this.indexBuffer = this.device.createBuffer({
      label: 'WaterSim Surface Indice', size: idx32.length * 4,
      usage: GPUBufferUsage.INDEX, mappedAtCreation: true
    });
    new Uint32Array(this.indexBuffer.getMappedRange()).set(idx32);
    this.indexBuffer.unmap();
  }

  _createSurfacePipelines() {
    this.modelBuffer = this.device.createBuffer({
      label: "WaterSim Model Buff",
      size: 96,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
    });

    this.surfaceBindGroupLayout = this.device.createBindGroupLayout({
      label: 'WaterSim Surface BGL',
      entries: [
        {binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: {type: 'uniform'}},
        {binding: 1, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: {type: 'uniform'}},
        {binding: 2, visibility: GPUShaderStage.FRAGMENT, buffer: {type: 'uniform'}},
        {binding: 3, visibility: GPUShaderStage.FRAGMENT, buffer: {type: 'uniform'}},
        {binding: 4, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, sampler: {}},
        {binding: 5, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, texture: {}},
        {binding: 6, visibility: GPUShaderStage.FRAGMENT, sampler: {}},
        {binding: 7, visibility: GPUShaderStage.FRAGMENT, texture: {}},
        {binding: 8, visibility: GPUShaderStage.FRAGMENT, texture: {}}
      ]
    });

    const layout = this.device.createPipelineLayout({bindGroupLayouts: [this.surfaceBindGroupLayout]});
    const vsModule = this.device.createShaderModule({label: 'WaterSim S VS', code: surfaceVertShaderSphere});
    const fsModule = this.device.createShaderModule({label: 'WaterSim S FS', code: surfaceFragShaderSphere});

    const baseDesc = {
      layout,
      vertex: {
        module: vsModule,
        entryPoint: 'vs_main',
        buffers: [{arrayStride: 12, attributes: [{shaderLocation: 0, offset: 0, format: 'float32x3'}]}]
      },
      fragment: {
        module: fsModule, entryPoint: 'fs_main', targets: [
          {format: this.format, blend: this.gpuBlend},
          {format: this.format}, {format: this.format}
        ]
      },
      primitive: {topology: 'triangle-list'},
      depthStencil: {depthWriteEnabled: true, depthCompare: 'less', format: 'depth24plus'}
    };

    this.surfacePipelineAbove = this.device.createRenderPipeline({
      ...baseDesc, label: 'WaterSim S Above',
      primitive: {topology: 'triangle-list', cullMode: 'back'}
    });
    this.surfacePipelineUnder = this.device.createRenderPipeline({
      ...baseDesc, label: 'WaterSim S Under',
      depthStencil: {depthWriteEnabled: false, depthCompare: 'less-equal', format: 'depth24plus'},
      primitive: {topology: 'triangle-list', cullMode: 'front'}
    });

    const makeBG = (waterView) => this.device.createBindGroup({
      layout: this.surfaceBindGroupLayout,
      entries: [
        {binding: 0, resource: {buffer: this.commonUniformBuffer}},
        {binding: 1, resource: {buffer: this.modelBuffer}},
        {binding: 2, resource: {buffer: this.lightUniformBuffer}},
        {binding: 3, resource: {buffer: this.waterUniformBuffer}},
        {binding: 4, resource: this.sampler},
        {binding: 5, resource: waterView},
        {binding: 6, resource: this.floorSampler},
        {binding: 7, resource: this.floorTexture.createView()},
        {binding: 8, resource: this.causticsTexture.createView()}
      ]
    });
    this._surfaceBindGroups = [makeBG(this._physViews[0]), makeBG(this._physViews[1])];
  }

  _createCausticsPipeline() {
    const vsModule = this.device.createShaderModule({label: 'WaterSim Caustics VS', code: causticsVertShader});
    const fsModule = this.device.createShaderModule({label: 'WaterSim Caustics FS', code: causticsFragShader});
    this.causticsPipeline = this.device.createRenderPipeline({
      label: 'WaterSim Caustics',
      layout: 'auto',
      vertex: {
        module: vsModule,
        entryPoint: 'vs_main',
        buffers: [{arrayStride: 12, attributes: [{shaderLocation: 0, offset: 0, format: 'float32x3'}]}]
      },
      fragment: {
        module: fsModule,
        entryPoint: 'fs_main',
        targets: [{
          format: 'rgba8unorm',
          blend: {
            color: {srcFactor: 'src-alpha', dstFactor: 'one-minus-src-alpha', operation: 'add'},
            alpha: {srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add'}
          }
        }]
      },
      primitive: {topology: 'triangle-list'}
    });
    const makeBG = (waterView) => this.device.createBindGroup({
      layout: this.causticsPipeline.getBindGroupLayout(0),
      entries: [
        {binding: 0, resource: {buffer: this.lightUniformBuffer}},
        {binding: 1, resource: {buffer: this.waterUniformBuffer}},
        {binding: 2, resource: this.sampler},
        {binding: 3, resource: waterView}
      ]
    });
    this._causticsBindGroups = [makeBG(this._physViews[0]), makeBG(this._physViews[1])];
  }

  addDrop(x, z, radius = 0.03, strength = 0.01) {
    this._dropQueue.push({x, z, radius, strength});
  }

  stampSphere(oldCenter, newCenter, radius) {
    this._sphereStamp = {oldCenter, newCenter, radius};
  }

  setLightDirection(x, y, z) {
    this.lightDirection = [x, y, z];
    this._writeLightUniforms();
  }

  updateWaterParameters(ior = 0.25, fresnelMin = 0.3, causticIntensity = 0.3, poolHeight = 0.1) {
    this.ior = ior;
    this.fresnelMin = fresnelMin;
    this.causticIntensity = causticIntensity;
    this.poolHeight = poolHeight;
  }

  simulate(commandEncoder) {
    const encoder = commandEncoder ?? this.device.createCommandEncoder({label: 'WaterSim Frame'});
    for(const drop of this._dropQueue) {
      this._dropUniform[0] = drop.x; this._dropUniform[1] = drop.z; this._dropUniform[2] = drop.radius; this._dropUniform[3] = drop.strength;
      this._runSimPass(encoder, this.dropPipeline, this._dropUniform);
    }
    this._dropQueue.length = 0;
    if(this._sphereStamp) {
      const {oldCenter, newCenter, radius} = this._sphereStamp;
      const su = this._sphereUniform;
      su[0] = oldCenter[0]; su[1] = oldCenter[1]; su[2] = oldCenter[2]; su[3] = radius;
      su[4] = newCenter[0]; su[5] = newCenter[1]; su[6] = newCenter[2]; su[7] = 0;
      this._runSimPass(encoder, this.spherePipeline, su);
      this._sphereStamp = null;
    }
    this._runSimPass(encoder, this.updatePipeline, this._deltaUniform);
    this._runSimPass(encoder, this.updatePipeline, this._deltaUniform);
    this._runSimPass(encoder, this.normalPipeline, this._deltaUniform);
    this._runCausticsPass(encoder);
    if(!commandEncoder) this.device.queue.submit([encoder.finish()]);
  }

  _runSimPass(encoder, pipelineObj, uniformData) {
    this.device.queue.writeBuffer(pipelineObj.uniformBuffer, 0, uniformData);
    const pass = encoder.beginRenderPass(this._simPassDescs[1 - this._parity]);
    pass.setPipeline(pipelineObj.pipeline);
    pass.setBindGroup(0, pipelineObj.bindGroups[this._parity]);
    pass.draw(6);
    pass.end();
    this._parity = 1 - this._parity;
  }

  _runCausticsPass(encoder) {
    const pass = encoder.beginRenderPass(this._causticsPassDesc)
    pass.setPipeline(this.causticsPipeline)
    pass.setBindGroup(0, this._causticsBindGroups[this._parity])
    pass.setVertexBuffer(0, this.positionBuffer)
    pass.setIndexBuffer(this.indexBuffer, this._indexFormat)
    pass.drawIndexed(this.indexCount)
    pass.end()
  }

  render(pass, mesh, viewProjMatrix) {
    const eye = this._lastEye ?? this._defaultEye;
    this.data.set(viewProjMatrix, 0);
    this.data.set(eye, 16);
    this.device.queue.writeBuffer(this.commonUniformBuffer, 0, this.data);
    pass.setPipeline(this.surfacePipelineAbove);
    pass.setBindGroup(0, this._surfaceBindGroups[this._parity]);
    pass.setVertexBuffer(0, this.positionBuffer);
    pass.setIndexBuffer(this.indexBuffer, this._indexFormat);
    pass.drawIndexed(this.indexCount);
    pass.setPipeline(this.surfacePipelineUnder);
    pass.setBindGroup(0, this._surfaceBindGroups[this._parity]);
    pass.drawIndexed(this.indexCount);
  }
  setEyePosition(pos) {this._lastEye = pos}
}